        Regiao regiao = parseRegiao(req.regiao());

        // 4. Modalidade de entrega.
        ModalidadeEntrega modalidade = registros.entregas().buscar(req.modalidadeEntrega())
                .orElseThrow(() -> new CheckoutException("MODALIDADE_INVALIDA"));

